// The type-position table as Markdown — the block `npm run docs:types` writes
// into `docs/language-reference/04-type-system.md`, and the drift test reads
// back.  Rendered from `src/language/type-positions.ts`, the same table the
// scope provider and the position checks read, so the docs cannot list a rule
// the compiler does not apply.

import { formLabel, positionRule, TYPE_FORMS, TYPE_POSITIONS } from "../language/type-positions.js";

const TYPE_POSITIONS_BEGIN =
  "<!-- type-positions:begin (generated by `npm run docs:types`) -->";
const TYPE_POSITIONS_END = "<!-- type-positions:end -->";

/** The generated block, markers included. */
function renderTypePositionsBlock(): string {
  const header = `| Position | ${TYPE_FORMS.map((f) => cell(formLabel(f))).join(" | ")} |`;
  const rule = `|---|${TYPE_FORMS.map(() => "---").join("|")}|`;
  const rows = TYPE_POSITIONS.filter((p) => p.position !== "other").map((p) => {
    const cells = TYPE_FORMS.map((form) => {
      const r = positionRule(form, p.position);
      if (r.verdict === "allowed") return "✓";
      if (r.verdict === "with-error-variant") return "✓ with an `error` variant";
      if (r.verdict === "unwritable") return "—";
      return `\`${r.code}\``;
    });
    return `| ${capitalize(p.label)} | ${cells.join(" | ")} |`;
  });
  return [TYPE_POSITIONS_BEGIN, "", header, rule, ...rows, "", TYPE_POSITIONS_END].join("\n");
}

/** `doc` with its generated block replaced by the current one. */
export function withTypePositionsBlock(doc: string): string {
  const begin = doc.indexOf(TYPE_POSITIONS_BEGIN);
  const end = doc.indexOf(TYPE_POSITIONS_END);
  if (begin < 0 || end < begin) throw new Error("type-positions markers not found");
  return (
    doc.slice(0, begin) + renderTypePositionsBlock() + doc.slice(end + TYPE_POSITIONS_END.length)
  );
}

/** A table cell's text, with the column separator escaped. */
function cell(s: string): string {
  return s.replaceAll("|", "\\|");
}

function capitalize(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}
